 [['점호 시작! 오늘 준비 상태는?',['확인 안 했어요.','아무도 안 왔겠죠.','마이크와 콘텐츠 준비 완료!'],2],['아직 한 명이 안 들리는데?',['연결 상태 확인하고 잠깐 기다려요.','그냥 빼버려요.','모른 척 시작해요.'],0]],
 [['내 마이크 소리 괜찮아?',['내 소리만 들리면 돼요.','함께 음량 맞추고 채팅에도 확인해요.','그대로 해요.'],1],['동시에 말했네! 먼저 할래?',['계속 끼어들게요.','대화는 그만하죠.','먼저 이야기해요, 저는 다음에 할게요.'],2]],
 [['이번 주 새로운 도전 뭐가 좋을까?',['각자 장점을 모아 팀 미션을 해요!','준비 없이 무조건 크게 해요.','팬 의견은 빼요.'],0],['오늘 목표에 조금 못 미쳤네.',['다른 멤버 탓이에요.','잘된 점을 기록하고 다음 목표를 정해요.','다 포기해요.'],1]]
